// myheader.h
#ifndef MYHEADER_H
#define MYHEADER_H

#define SQUARE(x) ((x) * (x))

#ifdef DEBUG
    #define LOG(msg) printf("[DEBUG] %s\n", msg)
#else
    #define LOG(msg)              // expands to nothing when DEBUG isn't defined
#endif

#endif // MYHEADER_H

// main.c
#include <stdio.h>
#include "myheader.h"

int main() {
    printf("%d\n", SQUARE(5));   // 25
    LOG("Starting up");           // only prints if DEBUG was defined at compile time
    return 0;
}
